    @GameTest(structure=STRUCTURE)public void actualSequencePhaseLimitsConsumeOnlyMotionAndSurviveNativeBeReload(GameTestHelper h)throws Exception{
        var piston=setup(h,true,Direction.EAST,4,true);drive(piston,256);var context=SequenceContext.fromGearshift(SequencerInstructions.TURN_DISTANCE,piston.getTheoreticalSpeed(),1);var phase=new SequencePhase(h.absolutePos(B.west(6)),1);piston.applySequenceContext(context,phase);piston.assemble();var owner=piston.getMovedContraption();owner.setStalled(true);tick(h,piston,4);h.assertTrue(piston.offset==0&&piston.saveWithFullMetadata(h.getLevel().registryAccess()).getDoubleOr("SequencedOffsetLimit",-1)==1,"Actual stall consumes none of the requested translation");owner.setStalled(false);tick(h,piston,3);h.assertTrue(Math.abs(piston.offset-1)<.00001&&piston.isRunning(),"Native final step clamps to one requested block while retaining the owner");
        var data=piston.saveWithFullMetadata(h.getLevel().registryAccess());var copy=(MechanicalPistonBlockEntity)BlockEntity.loadStatic(h.absolutePos(B),h.getBlockState(B),data,h.getLevel().registryAccess());copy.setLevel(h.getLevel());h.getLevel().setBlockEntity(copy);drive(copy,256);copy.applySequenceContext(context,phase);tick(h,copy,3);h.assertTrue(Math.abs(copy.offset-1)<.00001&&copy.getMovedContraption()==owner,"Reload with unchanged real phase does not refill consumed sequence distance");
        copy.applySequenceContext(null,null);var dormant=copy.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(dormant.getDoubleOr("SequencedOffsetLimit",-1)==-1&&dormant.getDoubleOr("SequenceLimitRemaining",-1)==0,"Detached upstream context keeps the consumed receipt dormant");var rejoined=(MechanicalPistonBlockEntity)BlockEntity.loadStatic(h.absolutePos(B),h.getBlockState(B),dormant,h.getLevel().registryAccess());rejoined.setLevel(h.getLevel());h.getLevel().setBlockEntity(rejoined);drive(rejoined,256);rejoined.applySequenceContext(context,phase);tick(h,rejoined,3);h.assertTrue(Math.abs(rejoined.offset-1)<.00001&&rejoined.getMovedContraption()==owner,"Same persisted phase after disconnect and BE reload cannot replay consumed distance");
        rejoined.applySequenceContext(context,new SequencePhase(phase.origin(),2));tick(h,rejoined,3);h.assertTrue(Math.abs(rejoined.offset-2)<.00001&&rejoined.getMovedContraption()==owner,"Equal-RPM new actual phase grants the next distance to the same native owner");ownedCargo(h,owner);h.succeed();
    }
    @GameTest(structure=STRUCTURE)public void realActorStopCannotReenterAndUnmountPistonCargoTwice(GameTestHelper h)throws Exception{
        var active=new AtomicBoolean(true);var called=new AtomicBoolean();var reference=new java.util.concurrent.atomic.AtomicReference<MechanicalPistonBlockEntity>();
        var actor=new MovementBehaviour(){@Override public void stopMoving(com.simibubi.create.content.contraptions.behaviour.MovementContext context){if(!active.get())return;h.assertTrue(called.compareAndSet(false,true),"Actual mounted barrel actor stops once");h.assertFalse(reference.get().disassemble(),"Nested native controller restore cannot reenter the active transfer");h.assertTrue(context.contraption.getStorage().ownsContents(),"Nested request leaves cargo owned until the outer transfer finishes");}};
        MovementBehaviour.REGISTRY.registerProvider(block->active.get()&&block==Blocks.BARREL?actor:null);
        try{var piston=setup(h,false,Direction.EAST,3,true);reference.set(piston);drive(piston,256);piston.assemble();h.assertTrue(piston.disassemble()&&called.get(),"Outer real native restoration completes after actual actor callback");exactCargo(h,B.east());h.assertTrue(piston.getMovedContraption()==null&&!piston.isRunning(),"Only the completed outer transfer releases the accepted owner");}
        finally{active.set(false);MovementBehaviour.REGISTRY.invalidate();}h.succeed();
    }
    @GameTest(structure=STRUCTURE,maxTicks=100)public void actualKineticShaftNetworkExtendsAndRetractsWithoutScriptedControllerTicks(GameTestHelper h){
        setup(h,false,Direction.EAST,3,true);h.setBlock(B.north(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.SOUTH));var motor=h.getBlockEntity(B.north(),com.simibubi.create.content.kinetics.base.KineticBlockEntity.class);motor.setGeneratedSpeed(-256);
        h.runAfterDelay(20,()->{var piston=h.getBlockEntity(B,MechanicalPistonBlockEntity.class);h.assertTrue(piston.getSpeed()<0&&!piston.isRunning()&&piston.offset==3,"Actual registered shaft network reaches source extension endpoint");h.assertBlockPresent(AllBlocks.MECHANICAL_PISTON_HEAD,B.east(3));exactCargo(h,B.east(4));motor.setGeneratedSpeed(256);});
        h.runAfterDelay(45,()->{var piston=h.getBlockEntity(B,MechanicalPistonBlockEntity.class);h.assertTrue(piston.getSpeed()>0&&!piston.isRunning()&&piston.offset==0&&h.getBlockState(B).getValue(MechanicalPistonBlock.STATE)==MechanicalPistonBlock.PistonState.RETRACTED,"Actual graph sign reversal returns the normal piston without a fake controller tick");for(int i=1;i<=3;i++)h.assertBlockPresent(AllBlocks.PISTON_EXTENSION_POLE,B.west(i));exactCargo(h,B.east(4));h.succeed();});
    }
